-- table: sys_dict（由 cmd/schema-split 生成；改结构直接改本文件）

-- @phase ddl
CREATE TABLE public.sys_dict (
    type character varying(16) NOT NULL,
    code character varying(16) NOT NULL,
    url_code character varying(16),
    iso639_1 character varying(8),
    iso639_2 character varying(8),
    ui_available boolean DEFAULT false NOT NULL,
    symbol character varying(8),
    minor_unit smallint,
    numeric_code character varying(8),
    enabled boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    create_time timestamp with time zone DEFAULT now() NOT NULL,
    update_time timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_sys_dict_currency CHECK ((((type)::text <> 'currency'::text) OR (minor_unit IS NOT NULL))),
    CONSTRAINT ck_sys_dict_language CHECK ((((type)::text <> 'language'::text) OR (url_code IS NOT NULL))),
    CONSTRAINT ck_sys_dict_type CHECK (((type)::text = ANY ((ARRAY['language'::character varying, 'currency'::character varying])::text[])))
);

-- @phase constr
ALTER TABLE ONLY public.sys_dict
    ADD CONSTRAINT sys_dict_pkey PRIMARY KEY (type, code);

-- @phase idx
CREATE INDEX idx_sys_dict_type_enabled ON public.sys_dict USING btree (type, enabled, sort_order);

-- @phase comment
COMMENT ON TABLE public.sys_dict IS '语言与货币字典（平面，type 判别）；名称不落库，由 i18n 运行时解析';

COMMENT ON COLUMN public.sys_dict.type IS '类别：language 语言 / currency 货币';

COMMENT ON COLUMN public.sys_dict.code IS '语言=完整语言码（zh-CN，与 sys_i18n.lang 同口径）/ 货币=ISO 4217 字母码（CNY）';

COMMENT ON COLUMN public.sys_dict.url_code IS '语言 URL 路径短码（zh / en），一律小写（zh-tw / en-gb）——URL 路径段惯例，且与项目内置短码映射同形，大写会对不上；仅为显式覆盖值，未收录语言的确定性回退在代码里';

COMMENT ON COLUMN public.sys_dict.iso639_1 IS 'ISO 639-1 两字母码（仅语言行，可空）';

COMMENT ON COLUMN public.sys_dict.iso639_2 IS 'ISO 639-2 三字母码（仅语言行，可空）';

COMMENT ON COLUMN public.sys_dict.ui_available IS '该语言是否已有后台界面译文（seed 时按 sys_i18n 实际语种填充的快照，不随 sys_i18n 自动更新；给 sys_i18n 增加界面语种时必须同步更新本列）';

COMMENT ON COLUMN public.sys_dict.symbol IS '货币符号（仅货币行，如 ¥ / $ / €）';

COMMENT ON COLUMN public.sys_dict.minor_unit IS '货币小数位（仅货币行，ISO 4217：JPY=0 / CNY=2 / KWD=3）——金额计算必需';

COMMENT ON COLUMN public.sys_dict.numeric_code IS 'ISO 4217 数字码（仅货币行）';

COMMENT ON COLUMN public.sys_dict.enabled IS '是否启用（停用即不在下拉出现，不物理删除）';

COMMENT ON COLUMN public.sys_dict.sort_order IS '同类型内的展示顺序';

-- @phase data
